shots.draw_js:
clearScene();setBig(null);setEq(null);
note("只用前 m 个样本",640,290,"y lg");
note("之后的全部扔掉",640,360,"r lg");
setCap("算法里写着一条很奇怪的规定：每个 (s,a) <b>只用前 m 个样本</b>。");

clearScene();setEq(null);
setBig("这肯定是笔误","哪有算法嫌数据多的");
setCap("讲师自己点破了这有多反常 —— 然后说明<b>为什么非这样不可</b>。");

clearScene();setBig(null);setEq(null);
note("并集界要覆盖每一次估计更新",640,280,"y lg");
note("所以更新次数必须有限",640,345,"r lg");
note("于是每个 (s,a) 封顶 m",640,410,"g lg");
setCap("<b>并集界逼出来的</b>：要盖住所有更新，更新次数就不能是无穷。");

clearScene();setBig(null);setEq(null);
saGrid({y:160,sLab:1,aLab:1,
  fill:function(i,j){return Math.min(1,0.18+((i*7+j*3)%11)/11);},
  bar:function(i,j){return ((i*7+j*3)%11)>8?"g":"y";}});
note("每格封顶 m=100",640,306,"sm");
note("10 × 4 × 100 = 4000",640,340,"g");
note("|S|·|A|·m",640,390,"y");
setCap("预算 = <b>|S|·|A|·m</b>。有限，所以失败概率加得起来。");

clearScene();setBig(null);setEq(null);
E.gS.append("path").attr("class","axline").attr("d","M300,280L1010,280");
for(var k=0;k<30;k++){
  var x=310+k*23, keep=k<14;
  E.gS.append("path").attr("class","axline "+(keep?"g":"sm"))
    .attr("opacity",keep?1:0.4).attr("d","M"+x+",256L"+x+",280");
  if(!keep)E.gS.append("path").attr("class","axline r").attr("opacity",0.5)
    .attr("d","M"+(x-7)+",262L"+(x+7)+",274");}
E.gS.append("path").attr("class","axline y").attr("d","M632,226L632,300");
note("第 m 个",632,216,"y");
note("这些进模型",420,320,"g");
note("第 m 个之后全扔",860,320,"r");
note("实践中不会这么做",640,390,"y");
setCap("<b>指名反驳</b>：不是笔误。但也<b>不是优点</b> —— 是为了拿到定理付的价。");

clearScene();setBig(null);
setEq("$$\\tilde{R}(s,a)=\\hat{R}(s,a)+\\frac{\\beta}{\\sqrt{n}}$$","top");
note("要证这个加成「够大」",640,330,"y lg");
setCap("三条条件里的第一条：证明 <b>β/√n 大到足以让算出的 Q 乐观</b>。");

clearScene();setEq(null);
setBig("1/√n 是挑出来的","衰减快慢调一调就行");
setCap("<b>不是挑的</b>。换成别的幂次，Hoeffding 里的 n <b>就不会抵消</b>。");

clearScene();setBig(null);
setEq("$$P\\big(|\\bar{X}-\\mathbb{E}X|\\ge t\\big)\\le 2\\exp\\!\\Big(\\!-\\frac{2nt^2}{R^2}\\Big),\\qquad R=\\frac{1}{1-\\gamma}$$","top");
note("取值范围宽度",880,340,"v lg");
note("这个前提讲座没念出来",640,400,"r lg");
setCap("Hoeffding 的一般形式。这里被平均的量落在<b>宽度 1/(1−γ)</b> 的范围里。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1,2,3],step:420,vals:[0.18,0.18,0.18,0.18],
  x:330,y:350,w:620,h:150,max:0.24,
  label:function(i){return ["n=1","10","10³","10⁵"][i];},
  cls:function(i){return "g";},
  fmt:function(v){return v.toFixed(4);}});
note("|Hoeffding 指数|",640,392,"sm");
setCap("代入 t = β/√n：<b>n 精确地约掉</b>。四个 n 差十万倍，指数完全相同。");

clearScene();setBig(null);
setEq("$$\\beta=\\frac{1}{1-\\gamma}\\sqrt{\\tfrac12\\ln\\frac{2|S||A|m}{\\delta}}\\ \\Longrightarrow\\ e^{-2\\beta^2(1-\\gamma)^2}=\\frac{\\delta}{2|S||A|m}$$","top");
note("双侧 × |S||A|m 次 = δ",640,340,"g lg");
setCap("<b>指名反驳</b>：1/√n 不是挑的。β 也不是 —— 它是从<b>总预算 δ</b> 倒推的。");

clearScene();setBig(null);setEq(null);
note("准确性条件：值要接近",640,280,"y lg");
note("接近谁？",640,350,"r lg");
setCap("第二条条件说「算出来的值要够接近」。<b>接近谁</b>，是这一集全部的内容。");

clearScene();setEq(null);
setBig("跟真 MDP 比","不然还能跟谁比");
setCap("跟真 MDP 比<b>做不到</b> —— 没探索过的地方，你对它一无所知。");

clearScene();setBig(null);setEq(null);
function chain(x0,y0,cls,rlab){
  for(var k=0;k<3;k++){
    E.gS.append("circle").attr("class","tnode "+(k===1?cls:"")).attr("cx",x0+k*104)
      .attr("cy",y0).attr("r",17);
    if(k<2)E.gS.append("path").attr("class","tedge").attr("d","M"+(x0+k*104+17)+","+y0+"L"+(x0+(k+1)*104-17)+","+y0);}
  note(rlab,x0+104,y0+44,cls);}
chain(330,214,"sm","R̂(s,a)");
chain(760,214,"g","R̂ + β/√n");
note("M̂",330,178,"sm");note("M̃",760,178,"g");
note("同一个 T̂",640,290,"sm");
note("名字像，差别只在奖励",640,390,"y");
setCap("先分清两个：<b>M̂ 与 M̃ 共用同一个转移模型，只差那个奖励加成</b>。");

clearScene();setBig(null);setEq(null);
saGrid({y:164,
  cls:function(i,j){return ((i*3+j)%7<3)?"hl":"";},
  fill:function(i,j){return ((i*3+j)%7<3)?0.9:0.22;},
  bar:function(i,j){return ((i*3+j)%7<3)?"g":"r";}});
note("已知集：用真模型",430,310,"g");
note("其余：用 M̃",880,310,"r");
note("现实里不存在，只是分析工具",640,390,"y");
setCap("第三个：<b>M′</b> —— 在<b>已知</b>的 (s,a) 上用<b>真</b>模型，其余用 M̃。");

clearScene();setBig(null);setEq(null);
vLadder([{y:190,label:"V* 真 MDP",cls:"y"},
         {y:250,label:"V^π_t 在 M′",cls:"g"},
         {y:308,label:"V^π_t 真实",cls:"sm"}],360,900);
E.gS.append("path").attr("class","axline g").attr("d","M330,250L330,308");
E.gS.append("path").attr("class","axline g").attr("d","M322,250L338,250");
E.gS.append("path").attr("class","axline g").attr("d","M322,308L338,308");
note("比这一对",250,282,"g");
note("不是 V*，不是真 MDP",640,390,"y");
setCap("<b>指名反驳</b>：不跟真 MDP 比。跟 <b>π_t 在 M′ 上的值</b>比。");
